var names=DATA.names||{},strings=DATA.strings||{},lang='en',preferred='';
function normalize(value){var code=String(value||'en').replace('_','-').split('-')[0].toLowerCase();if(code==='no')code='nb';return names[code]?code:'en';}
try{var cached=root.OpenPanelNative&&root.OpenPanelNative.readCache('ui-language');if(cached)preferred=normalize(JSON.parse(cached));}catch(e){}
function lookup(key,code){var table=strings[code];return table&&Object.prototype.hasOwnProperty.call(table,key)?table[key]:undefined;}
function has(key){return lookup(key,'sk')!==undefined||lookup(key,'en')!==undefined;}
/* Fallback: chosen language, English, Slovak (master), then the key itself. */
function t(key,vars,language){
  if(typeof key!=='string')return key;
  var code=normalize(language||lang),text=lookup(key,code);
  if(text===undefined)text=lookup(key,'en');
  if(text===undefined)text=lookup(key,'sk');
  if(text===undefined)return key;
  if(vars)text=text.replace(/\{([a-zA-Z0-9_]+)\}/g,function(m,name){return Object.prototype.hasOwnProperty.call(vars,name)?String(vars[name]):m;});
  return text;
}
/* Backend messages: 'backend.key' or 'backend.key|{"param":"value"}'; params may themselves be encoded messages. */
function message(text,language,depth){
  if(typeof text!=='string')return text;
  depth=depth||0;
  var bar=text.indexOf('|'),key=bar<0?text:text.slice(0,bar),vars=null;
  if(!/^[a-z][a-z0-9_]*(\.[A-Za-z0-9_]+)+$/.test(key)||!has(key))return text;
  if(bar>=0){try{vars=JSON.parse(text.slice(bar+1));}catch(e){vars=null;}}
  if(vars&&depth<3)Object.keys(vars).forEach(function(name){vars[name]=message(String(vars[name]),language,depth+1);});
  return t(key,vars,language);
}
function register(code,table){strings[code]=Object.assign(strings[code]||{},table||{});}
/* Load extra keys (e.g. Studio) from <base>/<code>.json plus English and Slovak fallbacks. */
function load(base,code){
  code=normalize(code||lang);
  var wanted=[code,'en','sk'].filter(function(c,i,a){return a.indexOf(c)===i;});
  return Promise.all(wanted.map(function(c){
    return fetch(String(base).replace(/\/$/,'')+'/'+c+'.json').then(function(r){return r.ok?r.json():{};}).then(function(table){register(c,table);}).catch(function(){});
  }));
}
/* Elements declare text with data-i18n="key" and attributes with data-i18n-attr="title=key;aria-label=key". */
function apply(base){
  base=base||document;if(!base.querySelectorAll)return;
  var list=[].slice.call(base.querySelectorAll('[data-i18n],[data-i18n-attr]'));
  if(base.matches&&base.matches('[data-i18n],[data-i18n-attr]'))list.unshift(base);
  list.forEach(function(el){
    var key=el.getAttribute('data-i18n');if(key){var value=t(key);if(el.textContent!==value)el.textContent=value;}
    var attrs=el.getAttribute('data-i18n-attr');
    if(attrs)attrs.split(';').forEach(function(pair){var i=pair.indexOf('=');if(i>0){var name=pair.slice(0,i).trim(),value=t(pair.slice(i+1).trim());if(el.getAttribute(name)!==value)el.setAttribute(name,value);}});
  });
}
function setLanguage(value){
  lang=normalize(value);
  if(root.document){document.documentElement.lang=lang;apply(document);}
  try{document.dispatchEvent(new CustomEvent('aurelvi-language-changed',{detail:lang}));}catch(e){}
}
var api={names:names,strings:strings,normalize:normalize,t:t,has:has,message:message,register:register,load:load,apply:apply,setLanguage:setLanguage,
  getLanguage:function(){return lang;},preferred:function(fallback){return preferred||normalize(fallback);}};
root.AurelviI18n=api;
/* Panel only: language picker inside #settings, remembered by the native app. */
function mount(){
  if(!root.document)return;
  var settings=document.getElementById('settings');
  if(settings&&!document.getElementById('ui-language')){
    var label=document.createElement('label'),caption=document.createElement('span'),select=document.createElement('select');
    caption.setAttribute('data-i18n','common.language');select.id='ui-language';select.setAttribute('data-i18n-attr','aria-label=common.language');
    Object.keys(names).forEach(function(code){var option=document.createElement('option');option.value=code;option.textContent=names[code];select.appendChild(option);});
    select.value=api.preferred(lang);label.appendChild(caption);label.appendChild(select);settings.appendChild(label);
    select.onchange=function(){preferred=normalize(select.value);try{if(root.OpenPanelNative)root.OpenPanelNative.writeCache('ui-language',JSON.stringify(preferred));}catch(e){}setLanguage(preferred);};
  }
  setLanguage(api.preferred(lang));
  if(document.body&&root.MutationObserver){
    var scheduled=false;
    new MutationObserver(function(){if(scheduled)return;scheduled=true;Promise.resolve().then(function(){scheduled=false;apply(document);});}).observe(document.body,{childList:true,subtree:true});
  }
}
